const listReservasDetalle = `-- name: ListReservasDetalle :many
SELECT
    r.id_reserva,
    r.id_usuario,
    u.nombre AS usuario_nombre,
    u.apellido AS usuario_apellido,
    r.id_cancha,
    r.fecha_inicio,
    r.fecha_fin,
    r.id_estado,
    r.precio_total,
    r.observaciones,
    r.created_at,
    r.updated_at,
    c.nombre AS cancha_nombre,
    i.id_institucion,
    i.nombre AS institucion_nombre,
    d.id_deporte,
    d.nombre AS deporte_nombre,
    e.nombre AS estado_nombre
FROM reservas r
JOIN usuario u ON r.id_usuario = u.id_usuario
JOIN cancha c ON r.id_cancha = c.id_cancha
JOIN institucion i ON c.id_institucion = i.id_institucion
JOIN deporte d ON c.id_deporte = d.id_deporte
JOIN estados_reservas e ON r.id_estado = e.id_estados_reserva
ORDER BY r.fecha_inicio DESC
`

